import Foundation

/// Synthetic tone fixture for transport/state QA. It is not ElevenLabs speech or reviewed content.
enum PackagedNarrationFixture {
    static let tone = Data(base64Encoded: "")!
    static func package(_ base: LessonPackage) -> LessonPackage {
        var p = base
        p.book.id = "audio-verification-fixture"; p.book.title = "Offline audio verification"
        p.book.author = "Synthetic tone fixture"; p.book.coverageNote = "Synthetic test tones, not studio narration or authored book content."
        p.collectionRevision = 1
        var lesson = p.book.lessons[0]
        lesson.id = "audio-check"; lesson.revision = 1; lesson.title = "Offline audio check"
        lesson.scopeNote = "Each segment plays a short test tone. Cues and branching verify the player, not spoken quality."
        let kinds: [PageKind] = [.intro, .explanation, .story, .story, .application, .takeaway]
        lesson.pages = (0..<6).map { index in
            LessonPage(id: "screen-\(index)", kind: kinds[index], role: index == 2 || index == 3 ? .storyteller : .guide,
                title: "Audio check \(index + 1)", text: "A synthetic tone checks offline playback. This is verification content.",
                sourceIDs: index == 2 || index == 3 ? [] : [p.book.sources[0].id], isOriginalFiction: index == 2 || index == 3 ? true : nil)
        }
        lesson.questions = (0..<2).map { index in PracticeQuestion(id: "question-\(index)", prompt: "Which option completes this test?",
            choices: [AnswerChoice(id: "yes", text: "Complete the check", feedback: "This is the correct verification choice."),
                      AnswerChoice(id: "no", text: "Try the retry path", feedback: "You can retry this verification question.")], correctChoiceID: "yes") }
        lesson.narration = LessonNarrationBundle(schemaVersion: 1, segments: LessonNarration.allSegments(lesson).map {
            NarrationSegment(id: $0.id, assetID: "tone", role: $0.role, scriptSHA256: $0.sha256, durationMilliseconds: 1_200,
                cues: [NarrationCue(characterStart: 0, characterLength: $0.text.utf16.count, startMilliseconds: 0, endMilliseconds: 1_200)])
        })
        p.book.lessons = [lesson]; p.manifest = [IdeaManifestEntry(id: lesson.id, revision: lesson.revision)]
