    }
    @MainActor static func install(in store: LibraryStore) async throws {
        await store.ready()
        guard let base = store.catalog.packages.first, !store.books.contains(where: { $0.id == "audio-verification-fixture" }) else { return }
        let review = try await store.storage.review(package: package(base), catalog: store.catalog)
        await store.commitImport(review); store.importedBook = nil
